import boto3
import os


class CloudWatchLogsClient:
    def __init__(self, region_name=None):
        self.region_name = region_name or os.environ.get("AWS_REGION")
        if not self.region_name:
            raise ValueError("AWS_REGION must be provided or set in environment variables.")
        self.client = boto3.client("logs", region_name=self.region_name)

    def put_log_events(self, log_group_name, log_stream_name, log_events):
        response = self.client.put_log_events(
            logGroupName=log_group_name,
            logStreamName=log_stream_name,
            logEvents=log_events,
        )
        if response.get("rejectedLogEventsInfo") or response.get("rejectedEntityInfo"):
            raise RuntimeError("The logging service rejected the event")
        return response

    def filter_log_events(self, log_group_name, start_time, end_time, filter_pattern=None, limit=None):
        params = {
            "logGroupName": log_group_name,
            "startTime": start_time,
            "endTime": end_time,
        }
        if filter_pattern:
            params["filterPattern"] = filter_pattern
        if limit:
            params["limit"] = limit

        response = self.client.filter_log_events(**params)
        return response.get("events", [])

import json
from typing import Dict, Any

def normalize_log_event(event: Dict[str, Any]) -> Dict[str, Any]:
    """Normalizes a log event dictionary for ingestion."""
    # In a real application, this would involve more robust schema validation and transformation
    return {
        "timestamp": event.get("timestamp_ms"),
        "message": json.dumps(event.get("event")),
    }

def parse_log_entry(log_event: Dict[str, Any]) -> Dict[str, Any]:
    """Parses a log entry retrieved from the logging service."""
    message = log_event.get("message", "{}")
    try:
        parsed_message = json.loads(message)
    except json.JSONDecodeError:
        parsed_message = {"raw_message": message}

    return {
        "timestamp": log_event.get("timestamp"),
        "event": parsed_message,
        "logStreamName": log_event.get("logStreamName"),
        "logGroupName": log_event.get("logGroupName"),
    }

import time
import json
from observability_client import CloudWatchLogsClient
from observability_models import normalize_log_event

def write_correlated_logs(log_group_name, log_stream_name, correlation_id, events, region_name=None):
    client = CloudWatchLogsClient(region_name=region_name)
    log_events = []
    for event_data in events:
        payload = {
            "timestamp_ms": int(time.time() * 1000),
            "event": {
                "correlation_id": correlation_id,
                **event_data,
            }
        }
        normalized_event = normalize_log_event(payload)
        log_events.append({
            "timestamp": normalized_event["timestamp"],
            "message": normalized_event["message"],
        })

    response = client.put_log_events(log_group_name, log_stream_name, log_events)
    return {"submitted": True, "response": response}
